#pragma once
#include "../../support.hpp"
namespace algs {
template<class T>struct DoublyLinkedListNode{T value;std::weak_ptr<DoublyLinkedListNode>prev;std::shared_ptr<DoublyLinkedListNode>next;explicit DoublyLinkedListNode(T v):value(std::move(v)){} };template<class T>class DoublyLinkedList{using Node=DoublyLinkedListNode<T>;std::shared_ptr<Node>head,tail;int length=0;public:static DoublyLinkedList from(const std::vector<T>&v){DoublyLinkedList l;for(auto&x:v)l.pushBack(x);return l;}int size()const{return length;}std::optional<T>first()const{return head?std::optional<T>(head->value):std::optional<T>{};}std::optional<T>last()const{return tail?std::optional<T>(tail->value):std::optional<T>{};}std::shared_ptr<Node>pushBack(T v){auto n=std::make_shared<Node>(std::move(v));n->prev=tail;if(tail)tail->next=n;else head=n;tail=n;++length;return n;}std::shared_ptr<Node>pushFront(T v){auto n=std::make_shared<Node>(std::move(v));n->next=head;if(head)head->prev=n;else tail=n;head=n;++length;return n;}void unlink(std::shared_ptr<Node>n){if(auto p=n->prev.lock())p->next=n->next;else head=n->next;if(n->next)n->next->prev=n->prev;else tail=n->prev.lock();n->prev.reset();n->next.reset();--length;}std::optional<T>popBack(){if(!tail)return {};auto n=tail;unlink(n);return n->value;}std::optional<T>popFront(){if(!head)return {};auto n=head;unlink(n);return n->value;}bool remove(const T&v){for(auto n=head;n;n=n->next)if(n->value==v){unlink(n);return true;}return false;}std::vector<T>toArray()const{std::vector<T>r;for(auto n=head;n;n=n->next)r.push_back(n->value);return r;}std::vector<T>reversed()const{std::vector<T>r;for(auto n=tail;n;n=n->prev.lock())r.push_back(n->value);return r;}};
}
